#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <chrono>
#include <random>
using namespace std;

struct Data { int totalWays, totalSum; Data() : totalWays(0), totalSum(0) {} Data(int w, int s) : totalWays(w), totalSum(s) {} };

int totalComp, totalPers, mod;
vector<vector<int>> comb;

int rangeSum(int a, int b) { return (a + b) * (b - a + 1) / 2; }

vector<bool> visited2;
vector<Data> cache2;

Data calc2(int n) {
    if (n == 1) return Data(2, 0);
    if (visited2[n]) return cache2[n];
    Data result(0, 0);
    for (int i = 0; i < n; ++i) {
        int leftCount = i, rightCount = n - i - 1;
        Data leftRes = (leftCount == 0) ? Data(1, 0) : calc2(leftCount);
        Data rightRes = (rightCount == 0) ? Data(1, 0) : calc2(rightCount);
        int ways = (leftCount + 1) + (rightCount + 1);
        int sumAdd = rangeSum(0, leftCount) + rangeSum(0, rightCount);
        int mlt = comb[leftCount + rightCount][leftCount];
        result.totalWays = (result.totalWays + (long long)leftRes.totalWays * ways % mod * rightRes.totalWays % mod * mlt) % mod;
        result.totalSum = (result.totalSum + (long long)leftRes.totalSum * ways % mod * rightRes.totalWays % mod * mlt
                           + (long long)leftRes.totalWays * sumAdd % mod * rightRes.totalWays % mod * mlt
                           + (long long)leftRes.totalWays * ways % mod * rightRes.totalSum % mod * mlt) % mod;
    }
    visited2[n] = true;
    cache2[n] = result;
    return result;
}

vector<vector<bool>> visited1;
vector<vector<Data>> cache1;

Data calc1(int idx, int cnt) {
    if (totalComp - idx == cnt) return calc2(cnt);
    if (visited1[idx][cnt]) return cache1[idx][cnt];
    Data res(0, 0);
    for (int i = idx; i < totalComp; ++i) {
        int leftCount = i - idx;
        int rightCount = cnt - leftCount;
        if (rightCount < 0 || rightCount > totalComp - i - 1) continue;
        Data leftRes = (i == idx) ? Data(1, 0) : calc2(leftCount);
        Data rightRes = (i + 1 == totalComp) ? Data(1, 0) : calc1(i + 1, rightCount);
        int mlt = comb[leftCount + rightCount][leftCount];
        res.totalWays = (res.totalWays + (long long)leftRes.totalWays * rightRes.totalWays % mod * mlt) % mod;
        res.totalSum = (res.totalSum + (long long)leftRes.totalSum * rightRes.totalWays % mod * mlt
                        + (long long)leftRes.totalWays * rightRes.totalSum % mod * mlt) % mod;
    }
    visited1[idx][cnt] = true;
    cache1[idx][cnt] = res;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ncomp, npers, MOD;
    cin >> ncomp >> npers >> MOD;
    totalComp = ncomp;
    totalPers = npers;
    mod = MOD;
    comb.assign(ncomp + 1, vector<int>(ncomp + 1, 0));
    for (int i = 0; i <= ncomp; ++i) {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }
    visited2.assign(ncomp + 1, false);
    cache2.assign(ncomp + 1, Data());
    visited1.assign(ncomp + 1, vector<bool>(npers + 1, false));
    cache1.assign(ncomp + 1, vector<Data>(npers + 1));
    cout << calc1(0, npers).totalSum << "\n";
    return 0;
}
